def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters ensuring a nontrivial, valid instance.
# Constraints enforced:
# - fingers in [4,6]
# - wear_count in [6,9]
# - total_rings in [12,18]
# - special_rings in [3,6]
# - capacities between [2,6], non-uniform, sum of top used_fingers capacities >= wear_count
# - used_fingers in [3, fingers]
# - min_specials in [2, min(S, wear_count, used_fingers)]
# Additionally, ensure at least two distinct x-values contribute in the sum.

def compute_answer(assign):
    # Internal DP to check viability and answer magnitude
    R = assign['total_rings']
    S = assign['special_rings']
    M = assign['wear_count']
    F = assign['fingers']
    caps = assign['capacities']
    U = assign['used_fingers']
    L = assign['min_specials']

    if F != len(caps):
        return None
    if any(c < 1 for c in caps):
        return None
    if U > F or U < 1:
        return None
    if M < U:
        return None
    if S < 0 or S > R:
        return None
    if L < 0 or L > min(S, M, U):
        return None
    # DP for coefficients of z^m u^x y^u across fingers
    xmax = min(S, M)
    # dp[m][x][u]
    dp = [[[0 for _ in range(F+1)] for _ in range(xmax+1)] for _ in range(M+1)]
    dp[0][0][0] = 1
    for i in range(F):
        cap = caps[i]
        newdp = [[[0 for _ in range(F+1)] for _ in range(xmax+1)] for _ in range(M+1)]
        for m in range(M+1):
            for x in range(xmax+1):
                for u in range(F+1):
                    val = dp[m][x][u]
                    if val == 0:
                        continue
                    # t = 0 (unused finger)
                    if newdp[m][x][u] != 0:
                        newdp[m][x][u] += val
                    else:
                        newdp[m][x][u] = val
                    # t >= 1 up to capacity
                    max_t = cap if m <= M else 0
                    for t in range(1, min(cap, M - m) + 1):
                        # No special on this finger
                        newdp[m + t][x][u + 1] += val
                        # Special on this finger (adds factor t)
                        if x + 1 <= xmax:
                            newdp[m + t][x + 1][u + 1] += val * t
        dp = newdp
    # Helper combinatorics
    def nCk(n, k):
        if k < 0 or k > n:
            return 0
        # small n, safe integer comb
        num = 1
        den = 1
        for i in range(1, k+1):
            num *= n - (k - i)
            den *= i
        return num // den
    def fact(n):
        f = 1
        for i in range(2, n+1):
            f *= i
        return f
    total = 0
    contributing_x = 0
    for x in range(L, min(S, M, U) + 1):
        coeff = dp[M][x][U]
        if coeff > 0:
            contributing_x += 1
            total += coeff * nCk(S, x) * nCk(R - S, M - x) * fact(x) * fact(M - x)
    if total == 0:
        return None
    # Return total and contributing_x for difficulty checks
    return total, contributing_x

